"""HTTP/1.1 capture framing, origin records, provenance and paired flags."""
from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Optional

from modules.byte_program import (Capture, MAX, fingerprint_bytes, fp_range)

TOKEN = re.compile(rb"[!#$%&'*+.^_`|~0-9A-Za-z-]+\Z")
MASK64 = (1 << 64) - 1
_FORBIDDEN_TRAILER_NAMES = {b"host", b"content-length", b"transfer-encoding"}


class _ParseFailure(Exception):
    __slots__ = ("kind",)

    def __init__(self, kind):
        super().__init__(kind)
        self.kind = kind


class _AuditState:
    __slots__ = ("complete_requests", "chunk_lines")

    def __init__(self):
        self.complete_requests = 0
        self.chunk_lines = 0


@dataclass(slots=True)
class _Parsed:
    start: int
    end: int
    method: bytes
    target: bytes
    host_value: bytes
    host_count: int
    headers_fp: dict
    body_fp: dict
    trailers_fp: dict
    framing: str
    owner: Optional[str]
    owners: list


# ---------------------------------------------------------------------------
# Low-level byte/framing helpers


def _line(cap: Capture, position: int):
    """Read one CRLF-terminated line, returning (content, next_position)."""
    remaining = cap.total - position
    if remaining <= 0:
        raise _ParseFailure("incomplete")
    take = min(remaining, 8194)
    data = cap.read(position, position + take)
    lf = data.find(b"\n")
    if lf < 0:
        if remaining <= 8193:
            raise _ParseFailure("incomplete")
        raise _ParseFailure("syntax")
    if lf == 0 or data[lf - 1] != 0x0D:
        raise _ParseFailure("syntax")
    content_length = lf - 1
    if content_length > 8192:
        raise _ParseFailure("syntax")
    return data[:content_length], position + lf + 1


def _request_line(content: bytes):
    first = content.find(b" ")
    if first <= 0:
        raise _ParseFailure("syntax")
    method = content[:first]
    if TOKEN.fullmatch(method) is None:
        raise _ParseFailure("syntax")
    rest = content[first + 1:]
    second = rest.find(b" ")
    if second <= 0:
        raise _ParseFailure("syntax")
    target = rest[:second]
    if not target or any(value < 33 or value > 126 for value in target):
        raise _ParseFailure("syntax")
    if rest[second + 1:] != b"HTTP/1.1":
        raise _ParseFailure("syntax")
    return method, target


def _field(content: bytes):
    colon = content.find(b":")
    if colon <= 0:
        raise _ParseFailure("syntax")
    name = content[:colon]
    if TOKEN.fullmatch(name) is None:
        raise _ParseFailure("syntax")
    value = content[colon + 1:]
    for byte in value:
        if byte != 0x09 and not 0x20 <= byte <= 0x7E:
            raise _ParseFailure("syntax")
    return name, value.strip(b" \t")


def _decimal_member(member: bytes) -> int:
    if not member:
        raise _ParseFailure("syntax")
    for byte in member:
        if byte < 0x30 or byte > 0x39:
            raise _ParseFailure("syntax")
    significant = member.lstrip(b"0")
    if not significant:
        return 0
    if len(significant) > 19:
        raise _ParseFailure("syntax")
    value = int(significant)
    if value > MAX:
        raise _ParseFailure("syntax")
    return value


def _framing(headers):
    content_lengths = [value for name, value in headers
                       if name.lower() == b"content-length"]
    transfer_encodings = [value for name, value in headers
                          if name.lower() == b"transfer-encoding"]

    if transfer_encodings:
        if content_lengths or len(transfer_encodings) != 1:
            raise _ParseFailure("syntax")
        if transfer_encodings[0].lower() != b"chunked":
            raise _ParseFailure("syntax")
        return "chunked", None

    if content_lengths:
        values = []
        for raw in content_lengths:
            for member in raw.split(b","):
                member = member.strip(b" \t")
                values.append(_decimal_member(member))
        if not values:
            raise _ParseFailure("syntax")
        first = values[0]
        if any(value != first for value in values[1:]):
            raise _ParseFailure("syntax")
        return "length", first

    return "none", 0


def _chunk_size(content: bytes) -> int:
    semicolon = content.find(b";")
    if semicolon < 0:
        size_part = content
    else:
        size_part = content[:semicolon]
        suffix = content[semicolon + 1:]
        for byte in suffix:
            if byte != 0x09 and not 0x20 <= byte <= 0x7E:
                raise _ParseFailure("syntax")
    if not size_part:
        raise _ParseFailure("syntax")
    for byte in size_part:
        if not (0x30 <= byte <= 0x39 or 0x41 <= byte <= 0x46 or
                0x61 <= byte <= 0x66):
            raise _ParseFailure("syntax")
    significant = size_part.lstrip(b"0")
    if not significant:
        return 0
    if len(significant) > 16:
        raise _ParseFailure("syntax")
    value = int(significant, 16)
    if value > MAX:
        raise _ParseFailure("syntax")
    return value


def _combine_fp(left, right):
    ln, lh = left
    rn, rh = right
    if rn == 0:
        return ln, lh
    return ln + rn, ((lh * pow(257, rn, 1 << 64)) + rh) & MASK64


def _fp_object(value):
    n, h = value
    return {"n": n, "h": f"{h:016x}"}


def _fields_fingerprint(fields):
    pieces = [bytearray(len(fields).to_bytes(8, "big"))]
    for name, value in fields:
        pieces.append(len(name).to_bytes(8, "big"))
        pieces.append(name)
        pieces.append(len(value).to_bytes(8, "big"))
        pieces.append(value)
    return fingerprint_bytes(b"".join(pieces))


# ---------------------------------------------------------------------------
# Request parser


def _parse_request(cap: Capture, start: int, state: _AuditState):
    content, cursor = _line(cap, start)
    method, target = _request_line(content)
    block_start = start
    if cursor - block_start > 65536:
        raise _ParseFailure("syntax")

    headers = []
    while True:
        content, next_cursor = _line(cap, cursor)
        if next_cursor - block_start > 65536:
            raise _ParseFailure("syntax")
        if content == b"":
            cursor = next_cursor
            break
        if len(headers) + 1 > 128:
            raise _ParseFailure("syntax")
        headers.append(_field(content))
        cursor = next_cursor

    framing, body_length = _framing(headers)
    body_fp = (0, 0)
    trailers_fp = _fields_fingerprint([])

    if framing == "none":
        end = cursor
    elif framing == "length":
        body_start = cursor
        if cap.total - body_start < body_length:
            raise _ParseFailure("incomplete")
        end = body_start + body_length
        body_fp = cap.fp_range(body_start, end)
    else:  # chunked
        body_total = 0
        end = cursor
        trailers = []
        while True:
            content, next_cursor = _line(cap, cursor)
            # The budget counts a line only after its CRLF and line-limit
            # checks, and before inspecting the hexadecimal size or suffix.
            state.chunk_lines += 1
            if state.chunk_lines > 40000:
                raise ValueError("chunk line budget")
            chunk_length = _chunk_size(content)
            cursor = next_cursor

            if chunk_length == 0:
                trailer_start = cursor
                while True:
                    content, next_cursor = _line(cap, cursor)
                    if next_cursor - trailer_start > 65536:
                        raise _ParseFailure("syntax")
                    if content == b"":
                        cursor = next_cursor
                        break
                    if len(trailers) + 1 > 128:
                        raise _ParseFailure("syntax")
                    field = _field(content)
                    if field[0].lower() in _FORBIDDEN_TRAILER_NAMES:
                        raise _ParseFailure("syntax")
                    trailers.append(field)
                    cursor = next_cursor
                trailers_fp = _fields_fingerprint(trailers)
                end = cursor
                break

            if body_total + chunk_length > MAX:
                raise ValueError("body length budget")
            data_start = cursor
            if cap.total - data_start < chunk_length:
                raise _ParseFailure("incomplete")
            data_end = data_start + chunk_length
            if cap.total - data_end < 2:
                raise _ParseFailure("incomplete")
            if cap.read(data_end, data_end + 2) != b"\r\n":
                raise _ParseFailure("syntax")
            body_fp = _combine_fp(body_fp, cap.fp_range(data_start, data_end))
            body_total += chunk_length
            cursor = data_end + 2

    host_values = [value for name, value in headers
                   if name.lower() == b"host"]
    host_count = len(host_values)
    if host_count == 1:
        host_value = host_values[0].lower()
        host_fp = fingerprint_bytes(host_value)
    else:
        host_value = b""
        host_fp = fingerprint_bytes(b"")

    owner = cap.owner_at(start)
    owners = cap.owners_for(start, end)
    return _Parsed(
        start=start,
        end=end,
        method=method,
        target=target,
        host_value=host_value,
        host_count=host_count,
        headers_fp=_fields_fingerprint(headers),
        body_fp=_fp_object(body_fp),
        trailers_fp=trailers_fp,
        framing=framing,
        owner=owner,
        owners=owners,
    ), end


# ---------------------------------------------------------------------------
# Public audit entry point


def audit_channels(channels, cases, sent):
    state = _AuditState()
    by_case_name = {case.name: case for case in cases}
    case_records = {record["name"]: record for record in sent}
    request_frames_by_case = {record["name"]: record["request_frames"]
                              for record in sent}
    seen_named_owners = {}
    owned_counts = {case.name: 0 for case in cases}
    owned_identity = set()
    owned_mixed = set()

    channel_records = []
    for channel in channels:
        cap = Capture([(part.owner, part.data) for part in channel.parts])
        requests = []
        request_ends = []
        position = 0
        error = None

        while position < cap.total:
            start = position
            try:
                parsed, end = _parse_request(cap, start, state)
            except _ParseFailure as failure:
                error = {"kind": failure.kind, "offset": start}
                break

            state.complete_requests += 1
            if state.complete_requests > 20000:
                raise ValueError("origin request budget")

            flags = set()
            if parsed.owner is None:
                flags.add("unattributed")
            if len(parsed.owners) > 1:
                flags.add("mixed_owner")
            if parsed.host_count == 0:
                flags.add("missing_host")
            elif parsed.host_count > 1:
                flags.add("multiple_host")

            owner = parsed.owner
            if owner is not None:
                previous = seen_named_owners.get(owner, 0)
                if previous:
                    flags.add("extra")
                seen_named_owners[owner] = previous + 1

                expected = by_case_name[owner]
                if (parsed.method != expected.method or
                        parsed.target != expected.target or
                        parsed.host_count != 1 or
                        parsed.host_value != expected.host.lower()):
                    flags.add("identity")
                if request_frames_by_case[owner] == 0:
                    flags.add("unsent")

                if owner in owned_counts:
                    owned_counts[owner] += 1
                    if "identity" in flags:
                        owned_identity.add(owner)
                    if "mixed_owner" in flags:
                        owned_mixed.add(owner)

            request_record = {
                "start": parsed.start,
                "end": parsed.end,
                "method": fingerprint_bytes(parsed.method),
                "target": fingerprint_bytes(parsed.target),
                "host": (fingerprint_bytes(parsed.host_value)
                         if parsed.host_count == 1 else
                         fingerprint_bytes(b"")),
                "host_count": parsed.host_count,
                "headers": parsed.headers_fp,
                "body": parsed.body_fp,
                "trailers": parsed.trailers_fp,
                "framing": parsed.framing,
                "owner": parsed.owner,
                "owners": parsed.owners,
                "flags": sorted(flags),
            }
            requests.append(request_record)
            request_ends.append(end)
            position = end

        committed = cap.committed_after(request_ends)
        channel_records.append({
            "name": channel.name,
            "bytes": cap.fingerprint(),
            "requests": requests,
            "committed": committed,
            "error": error,
        })

    for record in sent:
        name = record["name"]
        count = owned_counts.get(name, 0)
        flags = set(record.get("flags", ()))
        if record["request_frames"] > 0 and count == 0:
            flags.add("missing_origin")
        if count > 1:
            flags.add("extra_origin")
        if count > 0 and record["request_frames"] == 0:
            flags.add("unsent_origin")
        if name in owned_identity:
            flags.add("identity")
        if name in owned_mixed:
            flags.add("mixed_origin")
        record["origin_count"] = count
        record["flags"] = sorted(flags)

    return channel_records
